import { getCurrentChannel, setChannel } from 'src/pages/api-base-url';

/**
 * DOCB-13487 (DEVO-135 renamed to nova) — keep the served bundle (root `/`
 * vs pinned `/nova/`) in sync with the org's release channel on EVERY page
 * load, not only the pages that happen to call `getProfile()`.
 *
 * `setChannel()` (src/pages/api-base-url.ts) already performs the two
 * same-origin redirects — strip `/nova` for a vesta org, add `/nova` for a
 * nova org — but it only runs as the final step of
 * `useUserStore().getProfile()` (src/store/User/user_details.store.ts:161).
 * getProfile() is NOT called on every page: `dashboard.vue`'s call is commented
 * out (~line 1171) and deep-links such as `/nova/documents`, `/nova/import`,
 * `/nova/field_validation_v1` and `/nova/analytics` mount no component that
 * fetches the profile. So a `vesta` org that loads/bookmarks one of those
 * `/nova/` URLs stays stuck on the nova bundle, and the mirror also holds: a
 * `nova` org that lands on a root deep-link stays on the vesta bundle instead
 * of its pinned one.
 *
 * This runs once per page load and reconciles BOTH directions:
 *   1. Fast path (no network): the release channel persisted in this
 *      same-origin LocalStorage disagrees with the serving bundle — persisted
 *      `vesta` while under `/nova/`, or persisted `nova` while on the root
 *      bundle. That is an unambiguous inconsistency, so redirect immediately
 *      via setChannel() without waiting on any fetch.
 *   2. Authoritative path (nova bundle only): the persisted channel AGREES
 *      with the nova bundle (`nova`). Because the nova bundle is the one
 *      that can TRAP a user, confirm against the org's real channel by fetching
 *      the profile once — catching the case where LocalStorage still says
 *      `nova` but the org was switched to `vesta` server-side. The root
 *      bundle is the safe default, so a `vesta`-on-root load does no fetch.
 *
 * Convergence (no loop): once a vesta org is redirected to the root bundle,
 * the persisted channel is `vesta` and the bundle is root → nothing to do; a
 * nova org redirected into `/nova/` resolves `nova` and stays.
 *
 * Injectable deps keep it unit-testable without a browser/store.
 */
export interface NovaChannelReconcileDeps {
  /** True when the document is being served by the pinned `/nova/` bundle. */
  isNovaBundle: () => boolean;
  /** Whether a valid session exists (async: may attempt a token refresh). */
  isAuthenticated: () => boolean | Promise<boolean>;
  /** Fetch the profile; its final step runs setChannel(channelFromOrgs(...)). */
  fetchProfile: () => Promise<unknown>;
}

export async function reconcileNovaChannel(
  deps: NovaChannelReconcileDeps,
): Promise<void> {
  const inNova = deps.isNovaBundle();
  const persisted = getCurrentChannel(); // 'nova' | 'vesta'

  // 1. Fast path — persisted channel and serving bundle disagree.
  if (inNova && persisted === 'vesta') {
    setChannel('vesta'); // strips /nova → redirect OUT to the root bundle
    return;
  }
  if (!inNova && persisted === 'nova') {
    setChannel('nova'); // adds /nova → redirect INTO the nova bundle
    return;
  }

  // 2. Authoritative path — persisted channel agrees with the NOVA bundle;
  //    confirm against the org's real channel (the nova bundle is the trap).
  //    Only meaningful for an authenticated session; an unauthenticated visitor
  //    is routed through login → prepare-dashboard, which reconciles itself.
  if (inNova && persisted === 'nova') {
    const authed = await deps.isAuthenticated();
    if (!authed) return;
    await deps.fetchProfile();
  }
}
