/**
 * Release-channel bundle reconciliation boot file (DOCB-13487, DEVO-135
 * renamed to nova).
 *
 * Runs on every app startup and keeps the served bundle (root `/` vs pinned
 * `/nova/`) in sync with the org's release channel — regardless of which page
 * was loaded. This closes the gap where the redirect only fired on pages that
 * happen to call getProfile() (dashboard, settings), leaving deep-links like
 * /nova/documents stuck on the nova bundle for a vesta org (and the mirror
 * for a nova org on a root deep-link). See src/utils/novaChannelReconcile.ts
 * for the full rationale and convergence argument.
 *
 * Fire-and-forget: reconciliation must never block or fail app startup.
 */
import { boot } from 'quasar/wrappers';
import { safeBoot } from 'src/utils/bootSafety';
import { reconcileNovaChannel } from 'src/utils/novaChannelReconcile';

export default boot(
  safeBoot('novaChannelReconcile', () => {
    if (typeof window === 'undefined' || !window.location) return;

    void reconcileNovaChannel({
      isNovaBundle: () =>
        (window.location.pathname || '').startsWith('/nova/'),
      isAuthenticated: async () => {
        try {
          const { useAuthTokenStore } = await import('src/store/main');
          const store = useAuthTokenStore();
          store.hydrateFromLocalStorage();
          return await store.isLoggedIn();
        } catch {
          return false;
        }
      },
      fetchProfile: async () => {
        try {
          const { useUserStore } = await import('src/store/main');
          await useUserStore().getProfile();
        } catch {
          // Best-effort: a failed profile fetch must not break boot. The
          // existing in-app getProfile paths (settings, prepare-dashboard)
          // remain as backups.
        }
      },
    }).catch(() => {
      // reconcileNovaChannel is already internally defensive; this is a final
      // guard so a rejected promise can never surface as an unhandled rejection.
    });
  }),
);
